package com.infosys.carbonfootprint.service.impl;
import com.infosys.carbonfootprint.dto.RecommendationDto; import com.infosys.carbonfootprint.repository.ActivityLogRepository; import com.infosys.carbonfootprint.service.RecommendationService; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RecommendationServiceImpl implements RecommendationService { private final ActivityLogRepository logs; public RecommendationServiceImpl(ActivityLogRepository logs){this.logs=logs;} public List<RecommendationDto> topEmissions(Long userId){return logs.findByUserIdOrderByActivityDateDescCreatedAtDesc(userId).stream().sorted(Comparator.comparing(a->a.getTotalEmission(),Comparator.reverseOrder())).limit(5).map(a->RecommendationDto.builder().activityLogId(a.getActivityLogId()).activityName(a.getActivityType().getActivityName()).categoryName(a.getCategory().getCategoryName()).totalEmission(a.getTotalEmission()).activityDate(a.getActivityDate()).build()).toList();} }